<?php
require_once dirname(__DIR__) . '/_common.php';$pageTitle='Kegiatan';$items=$pdo->query('SELECT k.*, (SELECT COUNT(*) FROM galeri_album a WHERE a.kegiatan_id=k.id) AS album_count FROM kegiatan k ORDER BY k.tanggal DESC,k.id DESC')->fetchAll();osis_admin_page_start($pageTitle);
?>
<div class="admin-page-actions"><p>Perbarui kalender kegiatan OSIS dan hubungkan album dokumentasi.</p><a class="button button-primary" href="<?=osis_e(osis_url('admin/kegiatan/tambah.php'))?>">＋ Tambah kegiatan</a></div><div class="admin-panel"><div class="table-scroll"><table class="data-table"><thead><tr><th>Kegiatan</th><th>Tanggal</th><th>Lokasi</th><th>Status</th><th>Album</th><th>Aksi</th></tr></thead><tbody><?php if($items):foreach($items as $item):?><tr><td><strong><?=osis_e($item['judul'])?></strong><small class="table-subtext"><?=osis_e(mb_strimwidth(strip_tags($item['deskripsi']),0,80,'…','UTF-8'))?></small></td><td><?=osis_e(osis_format_date($item['tanggal']))?></td><td><?=osis_e($item['lokasi']?:'—')?></td><td><span class="badge badge-soft"><?=osis_e(ucfirst($item['status']))?></span></td><td><?=(int)$item['album_count']?></td><td><div class="table-actions"><a class="table-action" href="<?=osis_e(osis_url('admin/kegiatan/edit.php?id='.(int)$item['id']))?>">Edit</a><form method="post" action="<?=osis_e(osis_url('admin/kegiatan/hapus.php'))?>" data-confirm="Hapus kegiatan ini? Album terkait tetap ada, tetapi tautannya dilepas."><?=osis_csrf_input()?><input type="hidden" name="id" value="<?=(int)$item['id']?>"><button class="table-action danger-text" type="submit">Hapus</button></form></div></td></tr><?php endforeach;else:?><tr><td colspan="6" class="empty-inline">Belum ada kegiatan.</td></tr><?php endif;?></tbody></table></div></div>
<?php osis_admin_page_end(); ?>
